<script setup>
import {ref,computed,watch} from 'vue'
import {request} from './client'
import {previewMode} from '../preview/mode'
const props=defineProps({rooms:{type:Array,default:()=>[]},initialClass:String,student:String,slip:String}),emit=defineEmits(['close'])
const classroom=ref(props.initialClass||props.rooms[0]?.name||''),recipient=ref(props.student||''),kind=ref(props.slip?'payment_approved':'class_scheduled'),session=ref(''),search=ref(''),data=ref(null),message=ref(null),busy=ref(false),error=ref(''),note=ref(''),requestId=ref(crypto.randomUUID())
const args=computed(()=>({classroom:classroom.value,student:recipient.value,kind:kind.value,session:session.value||null,slip:props.slip||null}))
async function run(fn){busy.value=true;error.value='';note.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){message.value=null;if(classroom.value)data.value=await request('whatsapp_templates','options',{classroom:classroom.value,search:search.value})}
async function preview(){await run(async()=>{message.value=await request('whatsapp_templates','preview',args.value)})}
async function send(){await run(async()=>{const result=await request('whatsapp_templates','send',{...args.value,request_id:requestId.value});note.value=result.message;message.value=null})}
watch([recipient,kind,session],()=>{message.value=null;requestId.value=crypto.randomUUID()})
watch(classroom,()=>{recipient.value=props.student||'';session.value='';search.value='';run(load)},{immediate:true})
</script>
<template><div class="modal-backdrop whatsapp-backdrop" @click.self="emit('close')"><section class="modal whatsapp-composer" role="dialog" aria-modal="true" aria-label="WhatsApp templates"><header><div><span class="eyebrow">GOLD + PLATINUM</span><h2>A timely little reminder.</h2></div><button class="icon-button" aria-label="Close WhatsApp templates" @click="emit('close')">×</button></header><p>Send a class update using an approved WhatsApp template.</p><p v-if="previewMode" class="field-help">Fictional preview. No WhatsApp message will be sent.</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="note" role="status">{{note}}</p><form @submit.prevent="preview"><label>Class<select v-model="classroom" required :disabled="!!initialClass"><option value="">Choose a class</option><option v-for="r in rooms" :key="r.name" :value="r.name">{{r.title}}</option></select></label><p v-if="data&&!data.available" class="template-lock">🔒 WhatsApp templates are included in Gold and Platinum. This class owner’s package: {{data.plan}}.</p><template v-if="data?.available"><div v-if="!student" class="recipient-search"><label>Find student by name or LMS ID<input v-model="search" placeholder="Search this class"></label><button type="button" class="button subtle" :disabled="busy" @click="run(load)">Search</button></div><label>Student<select v-model="recipient" required :disabled="!!student"><option value="">Choose a student</option><option v-if="student&&!data.students.some(s=>s.name===student)" :value="student">{{student}}</option><option v-for="s in data.students" :key="s.name" :value="s.name">{{s.full_name}} · {{s.name}}</option></select></label><small v-if="data.has_more">Showing the first 50 matches. Search to narrow the list.</small><label>Message template<select v-model="kind"><option v-if="slip" value="payment_approved">Payment approved · open your classroom</option><option value="enrolment_reminder">Enrolment / payment reminder</option><option value="class_scheduled">Your teacher scheduled a class</option></select></label><label v-if="kind==='class_scheduled'">Scheduled class<select v-model="session" required><option value="">Choose an upcoming session</option><option v-for="s in data.sessions" :key="s.name" :value="s.name">{{s.title}} · {{s.starts_at}}</option></select></label><p v-if="kind==='class_scheduled'&&!data.sessions.length">Schedule a session in this classroom first.</p><button class="button subtle" :disabled="busy">Preview message</button></template></form><section v-if="message" class="whatsapp-message"><span>TO {{message.recipient_name}} · {{message.recipient_id}}</span><p>{{message.body}}</p><p v-if="!message.eligible" class="field-help">The student needs to enable eligible WhatsApp updates in their profile.</p><p v-else-if="!message.configured" class="field-help">Your administrator must connect WhatsApp and configure an approved template for this recipient’s language.</p><button class="button primary" :disabled="busy||!message.eligible||!message.configured" @click="send">{{previewMode?'Simulate WhatsApp queue':'Queue WhatsApp message'}}</button><small>Queued does not mean delivered. Repeat clicks do not send the same reminder again.</small></section></section></div></template>
<style scoped>.whatsapp-backdrop{z-index:700!important}.whatsapp-composer{padding:28px;width:560px;max-width:calc(100vw - 32px);box-sizing:border-box}.whatsapp-composer header{display:flex;justify-content:space-between;gap:16px}.whatsapp-composer h2{margin:10px 0}.whatsapp-composer p{line-height:1.7}.whatsapp-composer label{display:grid;gap:8px;margin:16px 0;font-size:13px}.whatsapp-composer input,.whatsapp-composer select{width:100%;box-sizing:border-box;padding:11px;border:1px solid #dfd9e7;border-radius:8px;background:var(--surface,#fff);color:inherit;font:inherit;min-width:0}.recipient-search{display:flex;gap:10px;align-items:center}.recipient-search label{flex:1;min-width:0}.whatsapp-message{background:#f5f2fa;padding:20px;border-radius:12px;margin-top:20px;color:#22182e}.whatsapp-message>span{font-size:10px;letter-spacing:1px}.whatsapp-message small{display:block;margin-top:12px;font-size:11px;line-height:1.6}.template-lock{border:1px solid #e0d6eb;border-radius:12px;padding:18px}@media(max-width:600px){.whatsapp-composer{padding:20px}.recipient-search{display:block}}</style>
